record ErrorResponseDto(Instant timestamp, int status, String error, String message, String path) {

    static ErrorResponseDto of(HttpStatus status, String message, String path) {
        return new ErrorResponseDto(
                Instant.now(), status.value(), status.getReasonPhrase(), message, path);
    }
}

@ExceptionHandler(OrderNotFoundException.class)
ResponseEntity<ErrorResponseDto> handle(OrderNotFoundException ex, HttpServletRequest req) {
    var body = ErrorResponseDto.of(HttpStatus.NOT_FOUND, ex.getMessage(), req.getRequestURI());
    return ResponseEntity.status(HttpStatus.NOT_FOUND).body(body);
}

@ExceptionHandler(OutOfStockException.class)
ProblemDetail handleOutOfStock(OutOfStockException ex) {
    ProblemDetail p = ProblemDetail.forStatusAndDetail(HttpStatus.CONFLICT, ex.getMessage());
    p.setTitle("Brak dostepnosci");
    p.setProperty("unavailableItems", ex.unavailableItems);
    return p;
}
